// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(uint128 a, uint128 b, address actor, uint t1, uint t2) public {
        vm.assume(actor != address(0));
        vm.assume(t1 > block.timestamp && t2 > block.timestamp);
        vm.deal(actor, uint256(a) + uint256(b));
        vm.prank(actor);
        c.Put{value: a}(t1);
        vm.prank(actor);
        c.Put{value: b}(t2);
        (uint unlockTime, uint bal) = c.Acc(actor);
        assertTrue(bal == uint256(a) + uint256(b) && unlockTime == t2);
    }
}
